        int[][] A = { {1, 2}, {3, 4} };
        int[][] B = { {1, 2}, {3, 4} };

        boolean isEqual = true;

        if (A.length != B.length || A[0].length != B[0].length) {
            isEqual = false;
        } else {
            for (int i = 0; i < A.length; i++) {
                for (int j = 0; j < A[0].length; j++) {
                    if (A[i][j] != B[i][j]) {
                        isEqual = false;
                        break;
