    DisplayNameFormatter formatter;
    cout << formatter.formatDisplayName("  john doe  ") << endl;
    cout << formatter.formatDisplayName("ALICE") << endl;
    cout << formatter.formatDisplayName("  bob  ") << endl;
    return 0;
}
