import java.util.List;

class ReportExporter {
    public String exportCsv(List<String[]> rows) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows.size(); i++) {
            sb.append(String.join(",", rows.get(i)));
            if (i < rows.size() - 1) {
                sb.append("\n");
            }
        }
        return sb.toString();
    }
}

