using namespace std;

class ReportExporter {
public:
    string exportCsv(const vector<vector<string>>& rows) {
        string result;
        for (size_t i = 0; i < rows.size(); i++) {
            for (size_t j = 0; j < rows[i].size(); j++) {
                if (j > 0) result += ",";
                result += rows[i][j];
            }
            if (i < rows.size() - 1) result += "\n";
        }
        return result;
    }
};

