	return &Section{
		name:  name,
		books: make([]*Book, 0),
	}
}

func (s *Section) AddBook(book *Book) {
	s.books = append(s.books, book)
}

func (s *Section) CheckoutBook(title string) bool {
	for _, book := range s.books {
		if book.GetTitle() == title {
			if book.IsAvailable() {
				book.MarkCheckedOut()
				return true
			}
			return false
		}
	}
	return false
}

type Library struct {
	sections []*Section
}

func NewLibrary() *Library {
	return &Library{
		sections: make([]*Section, 0),
	}
}

