        <<interface>>
        +playAudio(audioFile)
        +stopAudio()
        +adjustAudioVolume(volume)
        +playVideo(videoFile)
        +stopVideo()
        +adjustVideoBrightness(brightness)
        +displaySubtitles(subtitleFile)
    }
    class AudioOnlyPlayer {
        +playAudio(audioFile)
        +stopAudio()
        +adjustAudioVolume(volume)
        +playVideo(videoFile) throws
