	minLevel LogLevel
	mu       sync.RWMutex
}

var (
	instance *Logger
	once     sync.Once
)

func GetInstance() *Logger {
	once.Do(func() {
		instance = &Logger{
			minLevel: INFO,
		}
	})
	return instance
}

func (l *Logger) SetLevel(level LogLevel) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.minLevel = level
}

func (l *Logger) log(level LogLevel, message string) {
	l.mu.RLock()
	minLevel := l.minLevel
	l.mu.RUnlock()

	if level >= minLevel {
		fmt.Printf("[%s] %s\n", level.String(), message)
	}
}

func (l *Logger) Debug(msg string) { l.log(DEBUG, msg) }
