func newPizza(builder *PizzaBuilder) Pizza {
	return Pizza{
		size:     builder.size,
		crust:    builder.crust,
		sauce:    builder.sauce,
		cheese:   builder.cheese,
		toppings: append([]string(nil), builder.toppings...),
	}
