	return fmt.Sprintf("Pizza{size='%s', crust='%s', sauce='%s', cheese='%s', toppings=[%s]}",
		p.size, p.crust, p.sauce, p.cheese, strings.Join(p.toppings, ", "))
}

type PizzaBuilder struct {
	size     string
	crust    string
	sauce    string
	cheese   string
	toppings []string
}

