		sb.WriteString(fmt.Sprintf("   %s\n", sec.Content))
	}
	if len(r.charts) > 0 {
		sb.WriteString("\n\nCharts: [")
		sb.WriteString(strings.Join(r.charts, ", "))
		sb.WriteString("]\n")
	}
	if r.footer != "" {
		sb.WriteString("\n--- ")
		sb.WriteString(r.footer)
		sb.WriteString(" ---")
	}
	return sb.String()
}

