        if (this.footer) {
            lines.push("");
            lines.push(`--- ${this.footer} ---`);
        }
        return lines.join("\n");
    }

    static Builder = class {
        titleVal: string;
        subtitleVal: string = "";
        sectionList: Section[] = [];
        chartList: string[] = [];
        footerVal: string = "";

        constructor(title: string) { this.titleVal = title; }

        subtitle(subtitle: string): this { this.subtitleVal = subtitle; return this; }

        addSection(heading: string, content: string): this {
