    void setStrategy(SortStrategy* strategy) {
        this->strategy = strategy;
    }

    void sortArray(vector<int> array) {
        vector<int> result = strategy->sort(array);
        cout << "Result: [";
        for (size_t i = 0; i < result.size(); i++) {
