        manager.executeCommand(new RenameFileCommand(fs, "app.java", "Main.java"));
        manager.executeCommand(new DeleteFileCommand(fs, "readme.md"));
        fs.listFiles();
        manager.undo();
        manager.undo();
        fs.listFiles();
    }
}
