    @Override
    public void apply(Order order) {
        if (order.isLoyalCustomer) {
            double discount = order.total * 0.10;
            order.total -= discount;
            System.out.println("LoyaltyDiscount: -$" + String.format("%.2f", discount) + " (10% off)");
        }
        forward(order);
    }
