        size_t end = text.find_last_not_of(" \t\n\r");
        string trimmed = (start == string::npos) " "" : text.substr(start, end - start + 1);
        cout << "TrimProcessor: trimmed whitespace" << endl;
        return forward(trimmed);
    }
};

