        <<interface>>
        +accept(ShapeVisitor)
    }

    class Circle {
        -radius: double
        +getRadius(): double
        +accept(ShapeVisitor)
    }

    class Rectangle {
        -width: double
        -height: double
        +getWidth(): double
        +getHeight(): double
        +accept(ShapeVisitor)
    }

    class ShapeVisitor {
        <<interface>>
        +visitCircle(Circle)
        +visitRectangle(Rectangle)
    }

    class AreaCalculatorVisitor {
        +visitCircle(Circle)
        +visitRectangle(Rectangle)
    }

    class SvgExporterVisitor {
        +visitCircle(Circle)
        +visitRectangle(Rectangle)
    }

    Shape <|.. Circle
    Shape <|.. Rectangle
    ShapeVisitor <|.. AreaCalculatorVisitor
    ShapeVisitor <|.. SvgExporterVisitor
    Shape --> ShapeVisitor : accepts

