from abc import ABC, abstractmethod

class Expression(ABC):
    @abstractmethod
    def accept(self, visitor):
        pass

class ExpressionVisitor(ABC):
    @abstractmethod
    def visit_number(self, number):
        pass

    @abstractmethod
    def visit_add(self, add):
        pass

    @abstractmethod
    def visit_multiply(self, multiply):
        pass

# Elements
class NumberExpr(Expression):
    def __init__(self, value):
        self.value = value

    def accept(self, visitor):
        visitor.visit_number(self)

class AddExpr(Expression):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def accept(self, visitor):
        self.left.accept(visitor)
        self.right.accept(visitor)
        visitor.visit_add(self)

class MultiplyExpr(Expression):
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def accept(self, visitor):
        self.left.accept(visitor)
        self.right.accept(visitor)
        visitor.visit_multiply(self)

# Visitors
class EvaluateVisitor(ExpressionVisitor):
    def __init__(self):
        self.stack = []

    def get_result(self):
        return self.stack[-1]

    def visit_number(self, number):
        self.stack.append(float(number.value))

    def visit_add(self, add):
        right = self.stack.pop()
        left = self.stack.pop()
        self.stack.append(left + right)

    def visit_multiply(self, multiply):
        right = self.stack.pop()
        left = self.stack.pop()
        self.stack.append(left * right)

class PrintVisitor(ExpressionVisitor):
    def __init__(self):
        self.stack = []

    def get_result(self):
        return self.stack[-1]

    def visit_number(self, number):
        self.stack.append(str(float(number.value)))

    def visit_add(self, add):
        right = self.stack.pop()
        left = self.stack.pop()
        self.stack.append(f"({left} + {right})")

    def visit_multiply(self, multiply):
        right = self.stack.pop()
        left = self.stack.pop()
        self.stack.append(f"({left} * {right})")

