            for d in self.devices:
                if isinstance(d, AirConditioner):
                    d.receive_command("OFF")
        elif event == "NIGHT_MODE":
            print("[SmartHomeHub] NIGHT_MODE activated. Turning off lights.")
            for d in self.devices:
                if isinstance(d, Lights):
                    d.receive_command("OFF")

