class WizardHistory {
private:
    stack<FormMemento> history;

public:
    void save(Form& form) {
        history.push(form.save());
    }

    void back(Form& form) {
        if (history.empty()) {
            cout << "No previous step." << endl;
            return;
        }
        form.restore(history.top());
        history.pop();
    }
};

